std::vector<Point2d> result;

// Check all pairs of segments
for (size_t i = 0; i < segments.size(); i++) {
    for (size_t j = i + 1; j < segments.size(); j++) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        // Get segment endpoints
        Point2d p1 = seg1.p1();
        Point2d p2 = seg1.p2();
        Point2d p3 = seg2.p1();
        Point2d p4 = seg2.p2();

        // Create CGAL segments
        typedef CGAL::Simple_cartesian<double> K;
        typedef K::Point_2 Point_2;
        typedef K::Segment_2 Segment_2;

        Segment_2 cgalSeg1(Point_2(p1.x(), p1.y()), Point_2(p2.x(), p2.y()));
        Segment_2 cgalSeg2(Point_2(p3.x(), p3.y()), Point_2(p4.x(), p4.y()));

        // Compute intersection
        auto intersection_result = CGAL::intersection(cgalSeg1, cgalSeg2);

        if (intersection_result) {
            if (const Point_2* p = boost::get<Point_2>(&*intersection_result)) {
                result.push_back(Point2d(CGAL::to_double(p->x()), CGAL::to_double(p->y())));
            }
        }
    }
}

return result;

